// openapiMeta returns Endpoint.Metadata with the ordered openapi block for key.
func openapiMeta(key string) map[string]any {
	raw, ok := openapiSpecs[key]
	if !ok {
		return nil
	}
	v, err := jsonx.Parse([]byte(raw))
	if err != nil {
		panic(err)
	}
	return map[string]any{"openapi": v}
}
